import 'package:flutter/material.dart';
import '../app_state.dart';
import '../services/location_service.dart';
import 'map_screen.dart';
import 'delivery_screen.dart';

class PrepareRouteScreen extends StatelessWidget{
 final AppState state; const PrepareRouteScreen({super.key,required this.state});
 Future<void> _locate(BuildContext c)async{if(state.reviewCount>0){ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('Revise ${state.reviewCount} endereço${state.reviewCount==1?'':'s'} antes de localizar a rota.')));return;}await state.locateConfirmed();if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('${state.locatedCount} endereços localizados. ${state.packages.length-state.locatedCount} pendentes.')));}
 Future<void> _optimize(BuildContext c)async{try{final p=await LocationService().current();await state.optimizeFrom(p.latitude,p.longitude);if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Rota organizada a partir da sua posição.')));}catch(e){if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('$e')));}}
 Future<void> _organizeLoad(BuildContext c)async{final controller=TextEditingController(text:'20');final result=await showDialog<int>(context:c,builder:(d)=>AlertDialog(title:const Text('Organizar carga automaticamente'),content:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('O app seguirá a ordem da rota e criará posições A-01, A-02… B-01… sem limitar a quantidade total de pacotes.'),const SizedBox(height:14),TextField(controller:controller,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Pacotes por grupo',helperText:'Ex.: 20. Você pode escolher outro tamanho.',border:OutlineInputBorder()))]),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(d,int.tryParse(controller.text)),child:const Text('Organizar'))]));controller.dispose();if(result!=null&&result>0){await state.organizePhysicalLoad(groupSize:result);if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Carga organizada. Os locais físicos aparecem em cada pacote.')));}}
 @override Widget build(BuildContext context)=>AnimatedBuilder(animation:state,builder:(context,_){final canLocate=state.reviewCount==0&&state.packages.isNotEmpty;final canOptimize=state.locatedCount>=2;final canMap=state.locatedCount>0;final canStart=state.locatedCount>0;return Scaffold(appBar:AppBar(title:const Text('Preparar rota')),body:ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${state.packages.length} pacotes',style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:4),Text('${state.reviewCount} precisam de revisão • ${state.locatedCount} localizados'),if(state.reviewCount>0)...[const SizedBox(height:10),Row(children:[const Icon(Icons.warning_amber,size:18),const SizedBox(width:6),Expanded(child:Text('Volte à tela anterior e confirme os endereços com ⚠️ para liberar a localização.'))])]]))),const SizedBox(height:12),FilledButton.icon(onPressed:state.locating||!canLocate?null:()=>_locate(context),icon:const Icon(Icons.location_searching),label:Padding(padding:const EdgeInsets.all(14),child:Text(state.locating?'Localizando...':'1. Localizar endereços'))),const SizedBox(height:10),FilledButton.tonalIcon(onPressed:canOptimize?()=>_optimize(context):null,icon:const Icon(Icons.route),label:const Padding(padding:EdgeInsets.all(14),child:Text('2. Otimizar minha rota'))),const SizedBox(height:10),FilledButton.tonalIcon(onPressed:canOptimize?()=>_organizeLoad(context):null,icon:const Icon(Icons.inventory_2_outlined),label:const Padding(padding:EdgeInsets.all(14),child:Text('3. Organizar carga'))),const SizedBox(height:10),OutlinedButton.icon(onPressed:canMap?()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>RouteMapScreen(packages:state.packages))):null,icon:const Icon(Icons.map),label:const Padding(padding:EdgeInsets.all(14),child:Text('4. Ver mapa completo'))),const SizedBox(height:24),FilledButton.icon(onPressed:canStart?()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>DeliveryScreen(state:state))):null,icon:const Icon(Icons.play_arrow),label:const Padding(padding:EdgeInsets.all(16),child:Text('INICIAR ENTREGAS'))),if(!canStart)const Padding(padding:EdgeInsets.only(top:10),child:Text('Localize pelo menos um endereço para iniciar as entregas.',textAlign:TextAlign.center))]));});
}
